import re, sys, workcell

def call(*args):
    r=workcell.call(*args)
    print(' '.join(args), '->',r.text,flush=True)
    if not r.ok: raise RuntimeError('command failed: '+' '.join(args))
    return r

def locate():
    t=call('vision','locate').text
    s=re.search(r'socket hole centre: x=([-\d.]+) y=([-\d.]+) mm, top at z=([-\d.]+)', t)
    p=re.search(r'peg: centre x=([-\d.]+) y=([-\d.]+) z=([-\d.]+) mm; lower end x=([-\d.]+) y=([-\d.]+) z=([-\d.]+) mm; tilt ([-\d.]+)',t)
    if not s or not p: raise RuntimeError('vision unavailable')
    return tuple(map(float,s.groups())),tuple(map(float,p.groups()))

def run_trial():
    call('trial','start')
    call('robot','pick','cap','--arm','left')
    call('robot','place','bin','--arm','left')
    call('robot','pick','peg','--arm','right')
    s,p=locate()
    call('robot','move','right',str(s[0]),str(s[1]),'130')
    # Observe the actual peg tip, not the right TCP: the right arm's encoders are uncalibrated.
    for i in range(4):
        s,p=locate(); dx=s[0]-p[3]; dy=s[1]-p[4]
        if max(abs(dx),abs(dy))<0.8: break
        if max(abs(dx),abs(dy))>12: raise RuntimeError('unexpected peg offset')
        call('robot','step','right',f'{dx:.2f}',f'{dy:.2f}','0')
    # Move close to the rim while still above it; continuously observe depth and force.
    s,p=locate()
    if p[5]<s[2]+8: raise RuntimeError('peg already too low before approach')
    while p[5]>s[2]-37:
        dz=-min(20,max(1,p[5]-(s[2]-38)))
        r=call('robot','step','right','0','0',f'{dz:.2f}')
        if 'stopped' in r.text.lower(): raise RuntimeError('contact force stop')
        s,p=locate()
        if p[6]>3: raise RuntimeError('excess peg tilt')
        if p[5]<s[2]+2 and max(abs(p[3]-s[0]),abs(p[4]-s[1]))>3:
            raise RuntimeError('peg not aligned with socket')
    if p[5]>s[2]-35: raise RuntimeError('not inserted deeply enough')
    call('robot','grip','right','open')
    call('robot','move','right',str(s[0]),str(s[1]),'160')
    s,p=locate()
    if p[5]>s[2]-34: raise RuntimeError('peg lifted out after release')
    r=call('trial','end')
    return 'SUCCESS' in r.text

success=1
for attempt in range(2,6):
    if success>=3: break
    try:
        if run_trial(): success+=1
    except Exception as exc:
        print('Attempt error:',repr(exc),flush=True)
        # Do not run another trial if this one is still active: operator review required.
        break
print('QUALIFICATION:',success,'successful trials; starts at most',attempt,flush=True)
